    ks = ['a', 'a']
    if k == 1:
        return ks
    ks = ['a', 'a', 'b', 'b', 'a']
    if k == 2:
        return ks
    # k >= 3, follows formula.
    msd = 2
    while msd < k:
        #create extension with msd.
        ks.extend([chr(ord('a') + msd), chr(ord('a') + msd-1), chr(ord('a') + msd)])
        for i in range(msd-1):
            ks.extend(chr(ord('a') + msd))
            ks.extend(chr(ord('a') + (msd-(2+i))))
