def primeDivisors(num):
    sqrtNum = int(num ** 0.5) + 1
    primes = []
    if not num & 1:
        primes.append(2)
        while not num & 1:
            num >>= 1
    f = 3
    while f < sqrtNum and num > 1:
        if num % f == 0:
            primes.append(f)
            while num % f == 0:
                num //= f
        f += 2
    if num > 1:
        primes.append(num)
    return primes    

def minMoves(n, a):
    num = sum(a)
    if num == 1:
        return None

    ans = float('inf')
    for p in primeDivisors(num):
        ansP = 0
        leftSum = 0
        for i in range(n):
            leftSum += a[i]
            leftSum %= p
            ansP += min(leftSum, p - leftSum)
        ans = min(ans, ansP)

    return ans

