class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if node:
                dfs(node.left)
                dfs(node.right)
                if node.left and node.right:
                    node.val+=node.left.val+node.right.val
                elif node.left and not node.right:
                    node.val+=node.left.val
                elif node.right:
