                for(int row=0; row < matrix.length; row++)
                    rSum[row] += matrix[row][right];

                TreeSet<Integer> set = new TreeSet<>();

                set.add(0);
                int cs = 0;

                for(int a: rSum){
                    cs += a;

                    Integer target = set.ceiling(cs-k);

