class Solution {
    public int maxNumberOfBalloons(String text) {
        final int[] cache = new int[5];
        cache[0] = 97;  // a
        cache[1] = 99;  
        cache[2] = 108; // l
        cache[3] = 110; // n
        cache[4] = 111; // o

