    public int maxNumberOfBalloons(String text) {
        final int[][] cache = new int[2][6];
        cache[0][0] = 97;  // a
        cache[0][1] = 99;  
        cache[0][2] = 108; // l
        cache[0][3] = 110; // n
        cache[0][4] = 111; // o

        // cacl letter frequencies
